package com.example.godmace.commands; import org.bukkit.command.*; import org.bukkit.entity.Player; import com.example.godmace.CustomItems; import java.util.*; public class GodMaceCommand implements CommandExecutor, TabCompleter { @Override public boolean onCommand(CommandSender s, Command c, String l, String[] a) { if(s instanceof Player p && p.isOp() && a.length>=3 && a[0].equalsIgnoreCase("item")) { switch(a[2].toLowerCase()) { case "mace": p.getInventory().addItem(CustomItems.DRAGON_MACE); break; case "dash": p.getInventory().addItem(CustomItems.DASH_RUNE); break; case "strength": p.getInventory().addItem(CustomItems.STRENGTH_RUNE); break; case "lifesteal": p.getInventory().addItem(CustomItems.LIFESTEAL_RUNE); break; case "luck": p.getInventory().addItem(CustomItems.LUCK_RUNE); break; case "speed": p.getInventory().addItem(CustomItems.SPEED_RUNE); break; default: return true; } p.sendMessage("§aGave " + a[2]); return true; } return true; } @Override public List<String> onTabComplete(CommandSender s, Command c, String l, String[] a) { return a.length==1?Arrays.asList("item"):a.length==2?Arrays.asList("give"):a.length==3?Arrays.asList("mace","dash","strength","lifesteal","luck","speed"):new ArrayList<>(); } }